//! 📥️ STEP paths and standard annotations become editable native frames through canonical owned projections.
use super::*;
use semio_s_artifact_layout_layout_model::{CharacterStyle,ParagraphStyle,TextStyleRun};
use semio_s_artifact_stdio_step_snapshot::standards::v_ap214::subsets::base::io::draughting::{read_draughting,TextAnnotation};
fn rgba(value:Option<[f64;3]>)->Option<[f32;4]>{value.map(|rgb|[rgb[0]as f32,rgb[1]as f32,rgb[2]as f32,1.0])}
fn unique_id(wanted:&str,used:&mut std::collections::HashSet<String>)->String{let base=if wanted.is_empty(){"step-item"}else{wanted};if used.insert(base.into()){return base.into();}let mut index=2;loop{let id=format!("{base}-{index}");if used.insert(id.clone()){return id;}index+=1;}}
fn annotation(doc:&mut LayoutSnapshot,page:&mut Page,text:&TextAnnotation,min_x:f64,max_y:f64,used:&mut std::collections::HashSet<String>){if text.literal.is_empty(){return;}let id=unique_id(&text.name,used);let story_id=format!("story-{id}");let paragraph_id=format!("paragraph-{id}");let character_id=format!("character-{id}");doc.paragraph_styles.push(ParagraphStyle{id:paragraph_id.clone(),name:"STEP annotation".into(),font_family:"ISO 3098".into(),font_size:text.font_size,font_weight:400,leading:text.font_size*1.2,tracking:0.0,alignment:"left".into()});doc.character_styles.push(CharacterStyle{id:character_id.clone(),name:None,font_family:None,font_size:None,font_weight:None,italic:None,color:rgba(text.color),tracking:None});doc.stories.push(TextStory{id:story_id.clone(),content:text.literal.clone(),style_runs:vec![TextStyleRun{start:0,end:text.literal.len()as u64,paragraph_style_id:Some(paragraph_id),character_style_id:Some(character_id)}]});let bounds=super::geometry::annotation_bounds(text.position,text.x_axis,text.y_axis,text.width,text.font_size,min_x,max_y);page.layers[0].object_ids.push(id.clone());page.frames.push(Frame::Text{id,layer_id:page.layer_ids[0].clone(),bounds,story_id,thread_next:None,columns:1,inset:LayoutRect{x:0.0,y:0.0,width:0.0,height:0.0},wrap_mode:"none".into(),locked:None,visible:None});}
pub(crate) fn import(bytes:&[u8],name:&str,control:&mut InterchangeControl<'_>,drawing_sources:&mut Vec<PendingDrawingSource>)->Result<InterchangeResult<LayoutSnapshot>,String>{
 let graph=parse_part21(std::str::from_utf8(bytes).map_err(|error|error.to_string())?).map_err(|error|error.to_string())?;let view=analyze_brep_mesh(&graph);let edges=project_edges(&graph)?;let drawing=read_draughting(&graph)?;if view.mesh.faces.is_empty()&&edges.curves.is_empty()&&drawing.texts.is_empty(){return Err("layout.step.no-supported-geometry".into());}if view.mesh.vertices.len()>MAX_INTERCHANGE_ITEMS||view.mesh.faces.len()>MAX_INTERCHANGE_ITEMS{return Err("layout.interchange.item-limit".into());}
 let envelope=graph.by_type("MANIFOLD_SOLID_BREP").any(|instance|instance.entity("MANIFOLD_SOLID_BREP").and_then(|values|values.first()).and_then(semio_s_artifact_stdio_contract::part21::Part21Value::as_str).is_some_and(|name|name.starts_with("Layout page ")));
 let(mut min_x,mut min_y,mut max_x,mut max_y)=(f64::INFINITY,f64::INFINITY,f64::NEG_INFINITY,f64::NEG_INFINITY);let mut include=|x:f64,y:f64|->Result<(),String>{if !x.is_finite()||!y.is_finite(){return Err("layout.step.non-finite".into());}min_x=min_x.min(x);min_y=min_y.min(y);max_x=max_x.max(x);max_y=max_y.max(y);Ok(())};
 for vertex in &view.mesh.vertices{if !vertex.z.is_finite(){return Err("layout.step.non-finite".into());}include(vertex.x*edges.unit_to_points,vertex.y*edges.unit_to_points)?;}
 if !envelope{for curve in &edges.curves{for point in &curve.points{include(point[0],point[1])?;}}for text in &drawing.texts{for(x,y)in[(0.0,0.0),(text.width,0.0),(text.width,text.height),(0.0,text.height)]{include(text.position[0]+text.x_axis[0]*x+text.y_axis[0]*y,text.position[1]+text.x_axis[1]*x+text.y_axis[1]*y)?;}}}
 check_dimensions(max_x-min_x,max_y-min_y)?;let mut doc=document(name);let mut page=page("page-1".into(),max_x-min_x,max_y-min_y);let mut used=std::collections::HashSet::new();
 if !envelope{for(index,face)in view.mesh.faces.iter().enumerate(){checkpoint(control,index,view.mesh.faces.len())?;let points=face.indices.iter().map(|&index|view.mesh.vertices.get(index).map(|vertex|[vertex.x*edges.unit_to_points,vertex.y*edges.unit_to_points,vertex.z*edges.unit_to_points]).ok_or("layout.step.face-index")).collect::<Result<Vec<_>,_>>()?;let mut outline=points;if let Some(first)=outline.first().copied(){outline.push(first);}if let Some(bounds)=super::geometry::rectangle_bounds(&outline,min_x,max_y){let id=unique_id(&format!("face-{}",index+1),&mut used);page.layers[0].object_ids.push(id.clone());page.frames.push(Frame::Rect{id,layer_id:page.layer_ids[0].clone(),bounds,fill:None,stroke:Some([0.0,0.0,0.0,1.0]),visible:None,locked:None});}}}
 let appearances=drawing.paints.iter().map(|paint|(paint.source_id,paint)).collect::<std::collections::HashMap<_,_>>();let instances=graph.instances.iter().map(|instance|(instance.id,instance)).collect::<std::collections::HashMap<_,_>>();let mut children=Vec::new();let mut styles=Vec::new();
 for(index,curve)in edges.curves.iter().enumerate(){checkpoint(control,index,edges.curves.len())?;let paint=appearances.get(&curve.source_id);if let Some(bounds)=super::geometry::rectangle_bounds(&curve.points,min_x,max_y){let wanted=instances.get(&curve.source_id).and_then(|instance|instance.entity("POLYLINE")).and_then(|args|args.first()).and_then(semio_s_artifact_stdio_contract::part21::Part21Value::as_str).unwrap_or("");let id=unique_id(wanted,&mut used);page.layers[0].object_ids.push(id.clone());page.frames.push(Frame::Rect{id,layer_id:page.layer_ids[0].clone(),bounds,fill:paint.and_then(|paint|rgba(paint.fill)),stroke:paint.map_or(Some([0.0,0.0,0.0,1.0]),|paint|rgba(paint.stroke)),locked:None,visible:None});continue;}
 let name=format!("step-curve-{}",curve.source_id);let color=|color:[f64;3]|VectorRgba{r:color[0]as f32,g:color[1]as f32,b:color[2]as f32,a:1.0};styles.push(VectorStyle{name:name.clone(),fill:paint.and_then(|paint|paint.fill).map(color),stroke:paint.map_or(Some([0.0,0.0,0.0]),|paint|paint.stroke).map(color),stroke_width:Some(paint.and_then(|paint|paint.stroke_width).unwrap_or(0.5)),opacity:None});let segments=curve.points.iter().enumerate().map(|(index,point)|{let to=VectorPoint2{x:point[0]-min_x,y:max_y-point[1]};if index==0{VectorSegment::MoveTo{to}}else{VectorSegment::LineTo{to}}}).collect();children.push(VectorNode::Path{segments,style:Some(name)});
 }
 for(index,text)in drawing.texts.iter().enumerate(){checkpoint(control,index,drawing.texts.len())?;annotation(&mut doc,&mut page,text,min_x,max_y,&mut used);}
 doc.pages.push(page);finish_document(&mut doc);if !children.is_empty(){let scene=VectorScene{schema:String::new(),canvas:VectorCanvas{width:max_x-min_x,height:max_y-min_y,background:None},styles,layers:vec![VectorLayer{id:"step-edges".into(),name:"STEP XY edges".into(),visible:true,root:VectorNode::Group{transform:VectorTransform::identity(),children}}]};drawing_sources.push(PendingDrawingSource{source:semio_s_artifact_layout_layout_model::LayoutDrawingBirthSource::Page{page_id:doc.pages[0].id.clone()},scene});}
 let mut diagnostics=vec![diagnostic("layout.step.xy-projection","Orthogonal XY rectangle paths become editable center-rotated frames with standard RGB fill/stroke. Standard positioned Unicode text annotations become editable styled text frames in points. Each annotation fragment retains its placement; original story threads, font families and paragraph flow are not recoverable. The named Layout page solid defines the canvas and is not imported as duplicate content. Other supported curves retain per-curve appearance as an XY drawing trace. Image source annotations retain references, not pixels."),diagnostic("layout.step.source-schema",&format!("Declared Part21 FILE_SCHEMA: {:?}. Supported entity mapping does not establish application-protocol conformance.",graph.header.file_schema))];diagnostics.extend(edges.issues.iter().map(|issue|diagnostic("layout.step.edge-projection",issue)));diagnostics.extend(drawing.issues.iter().map(|issue|diagnostic("layout.step.annotation",issue)));diagnostics.extend(view.issues.iter().map(|issue|diagnostic("layout.step.geometry",&format!("#{}: {}",issue.entity_id,issue.reason))));Ok(InterchangeResult{value:doc,fidelity:"projection",diagnostics})
}
